<?php
require __DIR__ . '/bootstrap.php'; require_login();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$min=max(0,(float)($_POST['min_amount']??0));$max=max(0,(float)($_POST['max_amount']??0));$income=max(0,(float)($_POST['min_income']??0));$tenure=max(1,min(600,(int)($_POST['tenure_months']??12)));$rate=max(0,min(100,(float)($_POST['indicative_rate']??0)));if($name==='')$error='Product name is required.';elseif($max<$min)$error='Maximum amount must be greater than or equal to minimum amount.';else{if($id){$s=$pdo->prepare('UPDATE loan_products SET name=?,min_amount=?,max_amount=?,min_income=?,tenure_months=?,indicative_rate=? WHERE id=?');$s->execute([$name,$min,$max,$income,$tenure,$rate,$id]);}else{$s=$pdo->prepare('INSERT INTO loan_products (name,min_amount,max_amount,min_income,tenure_months,indicative_rate) VALUES (?,?,?,?,?,?)');$s->execute([$name,$min,$max,$income,$tenure,$rate]);}flash('Loan product saved.');header('Location: products.php');exit;}}
 if($action==='toggle'){$id=(int)($_POST['id']??0);$s=$pdo->prepare('UPDATE loan_products SET active=1-active WHERE id=?');$s->execute([$id]);flash('Product status updated.');header('Location: products.php');exit;}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM loan_products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$products=$pdo->query('SELECT * FROM loan_products ORDER BY active DESC,name')->fetchAll();$flash=get_flash();require __DIR__.'/partials/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">PRODUCT CONFIGURATION</p><h1>Loan products</h1><p class="muted">Maintain indicative product ranges used by your sales team.</p></div></div><?php if($flash):?><div class="alert <?=h($flash['type'])?>"><?=h($flash['message'])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<div class="content-grid products-layout"><section class="panel"><div class="panel-heading"><div><h2>Configured products</h2><p class="muted">Rates and criteria are indicative only.</p></div></div><div class="product-list"><?php foreach($products as $p):?><div class="product-row"><div class="product-symbol"><?=h(strtoupper(substr($p['name'],0,1)))?></div><div class="product-detail"><strong><?=h($p['name'])?></strong><small><?=money($p['min_amount'])?> – <?=money($p['max_amount'])?> · Up to <?=number_format($p['tenure_months'])?> months</small><div class="product-meta">Minimum income: <?=money($p['min_income'])?> · Indicative rate: <?=number_format($p['indicative_rate'],2)?>%</div></div><span class="status <?=$p['active']?'status-qualified':'status-closed'?>"><?=$p['active']?'Active':'Inactive'?></span><a class="icon-action" href="products.php?edit=<?=(int)$p['id']?>">↗</a><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="small-btn" title="Toggle active status">⏻</button></form></div><?php endforeach;?></div></section>
<section class="panel"><div class="panel-heading"><div><h2><?=$edit?'Edit product':'Add product'?></h2><p class="muted">Configure basic product information.</p></div><?php if($edit):?><a class="text-link" href="products.php">Cancel</a><?php endif;?></div><form method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Product name *<input name="name" required maxlength="120" value="<?=h($edit['name']??'')?>"></label><div class="form-grid"><label>Minimum amount (₹)<input type="number" name="min_amount" min="0" step="1000" value="<?=h($edit['min_amount']??'50000')?>"></label><label>Maximum amount (₹)<input type="number" name="max_amount" min="0" step="1000" value="<?=h($edit['max_amount']??'2500000')?>"></label><label>Minimum monthly income (₹)<input type="number" name="min_income" min="0" step="1000" value="<?=h($edit['min_income']??'20000')?>"></label><label>Tenure (months)<input type="number" name="tenure_months" min="1" max="600" value="<?=h($edit['tenure_months']??36)?>"></label><label>Indicative annual rate (%)<input type="number" name="indicative_rate" min="0" max="100" step="0.01" value="<?=h($edit['indicative_rate']??14.5)?>"></label></div><button class="btn primary full">Save product</button></form></section></div>
